Write-Host ""
Write-Host "=== Creating RedSight desktop/start-menu shortcut ==="

$Desktop = [Environment]::GetFolderPath("Desktop")
$StartMenuPrograms = Join-Path $env:APPDATA "Microsoft\Windows\Start Menu\Programs"

$DesktopShortcut = Join-Path $Desktop "RedSight.lnk"
$StartShortcut = Join-Path $StartMenuPrograms "RedSight.lnk"

$PowerShellExe = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
$ShortcutArgs = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $StartScript + '"'

$Wsh = New-Object -ComObject WScript.Shell

foreach ($ShortcutPath in @($DesktopShortcut,$StartShortcut)) {
    $Shortcut = $Wsh.CreateShortcut($ShortcutPath)
    $Shortcut.TargetPath = $PowerShellExe
    $Shortcut.Arguments = $ShortcutArgs
    $Shortcut.WorkingDirectory = $Root
    if (Test-Path $IconPath) {
        $Shortcut.IconLocation = $IconPath + ",0"
    }
    $Shortcut.Description = "RedSight Local Intelligence Command Center"
    $Shortcut.WindowStyle = 7
    $Shortcut.Save()
}

if (-not (Test-Path $DesktopShortcut)) {
    throw "RedSight desktop shortcut was not created."
}

Write-Host "DESKTOP_SHORTCUT=PASS"
Write-Host "START_MENU_SHORTCUT=PASS"

# Windows 11 does not always expose the TaskbarPin Shell verb to scripts.
# Attempt it without using unsupported Explorer registry hacks.
$TaskbarPinned = $false

try {
    $ShellApp = New-Object -ComObject Shell.Application
    $Folder = $ShellApp.Namespace((Split-Path $StartShortcut))
    $Item = $Folder.ParseName((Split-Path -Leaf $StartShortcut))

    if ($null -ne $Item) {
        $Verb = @($Item.Verbs()) |
            Where-Object {
                (($_.Name -replace '&','').Trim()) -match '(?i)pin.*taskbar|taskbar.*pin'
            } |
            Select-Object -First 1

        if ($null -ne $Verb) {
            $Verb.DoIt()
            Start-Sleep -Milliseconds 700
            $TaskbarPinned = $true
        }
    }
}
catch {
    $TaskbarPinned = $false
}

if ($TaskbarPinned) {
    Write-Host "TASKBAR_PIN=PASS"
}
else {
    Write-Host "TASKBAR_PIN=WINDOWS_SHELL_VERB_UNAVAILABLE"
    Write-Host "The branded RedSight shortcut is on the Desktop and Start menu."
}

