    messages = @(
        @{
            role = "user"
            content = "Reply with exactly REDSIGHT_STAGE102_READY"
        }
    )
    stream = $false
} | ConvertTo-Json -Depth 8

$Chat = Invoke-RestMethod `
    -Uri "http://127.0.0.1:8000/api/v1/chat" `
    -Method Post `
    -ContentType "application/json" `
    -Body $ChatBody `
