# ======================================================================
# SESSION LIFECYCLE VALIDATION
# ======================================================================

Write-Host ""
Write-Host "=== /new /reset /clear session backend validation ==="

$ActiveBefore = Invoke-RestMethod `
    -Uri "http://127.0.0.1:8765/memory/session/active" `
    -Method Get `
    -TimeoutSec 20

$OriginalSession = $ActiveBefore.session.id

$TempBody = @{ title = "Stage 10.2 UI Validation" } | ConvertTo-Json
$Temp = Invoke-RestMethod `
    -Uri "http://127.0.0.1:8765/memory/sessions/new" `
    -Method Post `
    -ContentType "application/json" `
    -Body $TempBody `
    -TimeoutSec 20

$TempId = $Temp.session.id
if (-not $TempId) {
    throw "Session creation endpoint did not return an id."
}

Invoke-RestMethod `
    -Uri "http://127.0.0.1:8765/memory/sessions/$OriginalSession/activate" `
    -Method Post `
    -TimeoutSec 20 | Out-Null

$ArchiveBody = @{ archived = $true } | ConvertTo-Json
Invoke-RestMethod `
    -Uri "http://127.0.0.1:8765/memory/sessions/$TempId/archive" `
    -Method Post `
    -ContentType "application/json" `
    -Body $ArchiveBody `
    -TimeoutSec 20 | Out-Null

$ActiveAfter = Invoke-RestMethod `
    -Uri "http://127.0.0.1:8765/memory/session/active" `
    -Method Get `
    -TimeoutSec 20

if ($ActiveAfter.session.id -ne $OriginalSession) {
    throw "Session lifecycle validation did not restore the original session."
}

Write-Host "SESSION_COMMAND_BACKEND=PASS"

